import SwiftUI

/// The web's stock colours, one per token in docs/brand/tokens.json, named as the token is (`muted-foreground` is
/// `mutedForeground`). Each is a single-appearance colour set in `Colors.xcassets`, generated by
/// scripts/gen_tokens.py, so the app, the Share extension and the widgets all draw the same value.
///
/// They are namespaced because SwiftUI already has `Color.primary` and `Color.secondary`, which mean label colours.
/// Screens use `Palette`, which is built from these; reach for `HVColor` where a token's own name is the point.
///
/// The stock look is dark only (handoff 2.2): the app declares `UIUserInterfaceStyle = Dark`, and nothing here
/// branches on the colour scheme. A light look would fill each colour set's Any slot and move the stock value to Dark.
enum HVColor {
    static let background = Color("background")
    static let foreground = Color("foreground")
    static let card = Color("card")
    static let cardForeground = Color("card-foreground")
    static let muted = Color("muted")
    static let mutedForeground = Color("muted-foreground")
    static let primary = Color("primary")
    static let primaryForeground = Color("primary-foreground")
    static let secondary = Color("secondary")
    static let secondaryForeground = Color("secondary-foreground")
    static let accent = Color("accent")
    static let accentForeground = Color("accent-foreground")
    static let border = Color("border")
    static let ring = Color("ring")
    static let destructive = Color("destructive")

    /// The status shades of the Agent keys chips (emerald-400 and amber-400). The web has no token for them; these
    /// are the clamped sRGB values the handoff gives, because Tailwind 4 defines the shades outside sRGB.
    static let emerald400 = Color("emerald-400")
    static let amber400 = Color("amber-400")
}
